homepageStrings:
[data-arrival] { padding-top: var(--ta-space-16); padding-bottom: var(--ta-space-12); }
        [data-arrival] h1 { max-width: 12ch; }
        [data-arrival-cta] { margin-top: var(--ta-space-6); }
        [data-arrival-support] { margin: var(--ta-space-4) 0 0; font-size: var(--ta-text-md); line-height: 1.6; }
        @media (max-height: 40rem) { [data-arrival-cue] { display: none; } }
        @media (max-height: 42rem), (max-width: 30rem) {
          [data-arrival] { padding-top: var(--ta-space-4); padding-bottom: var(--ta-space-12); }
          [data-arrival] h1 { max-width: 18ch; }
          [data-arrival-support] { margin-top: var(--ta-space-2); font-size: var(--ta-text-sm); }
          [data-arrival-cta] { margin-top: var(--ta-space-2); gap: var(--ta-space-2); }
          [data-arrival-support] { margin-top: var(--ta-space-2); }
        }

[data-premise] { max-width: var(--ta-container-prose); padding-block: var(--ta-space-block); }
        [data-premise-lead] { margin: var(--ta-space-4) 0 0; font-size: var(--ta-text-xl); line-height: 1.5; color: var(--ta-text-primary); text-wrap: pretty; }
        [data-premise-beats] { list-style: none; margin: var(--ta-space-block) 0 0; padding: var(--ta-space-block) 0 0; border-top: 1px solid var(--ta-brand-quiet); display: grid; gap: var(--ta-space-stack); }
        [data-premise-beats] h3 { margin: 0; font-family: var(--ta-font-display); font-weight: 500; font-size: var(--ta-text-lg); color: var(--ta-text-primary); }
        [data-premise-beats] p { margin: var(--ta-space-1) 0 0; font-size: var(--ta-text-md); line-height: 1.6; color: var(--ta-text-secondary); }
        [data-premise-beats] li { padding-block: var(--ta-space-2); }
        @media (max-width: 30rem) {
          [data-premise-lead] { font-size: var(--ta-text-lg); }
          [data-premise] { padding-block: var(--ta-space-6); }
          [data-premise-beats] { margin-top: var(--ta-space-6); padding-top: var(--ta-space-6); }
          [data-premise-beats] p { font-size: var(--ta-text-sm); }
        }

[data-difference] { padding-block: var(--ta-space-block); }
        [data-difference-lead] { margin: var(--ta-space-4) 0 0; max-width: var(--ta-measure); font-size: var(--ta-text-lg); line-height: 1.55; color: var(--ta-text-secondary); text-wrap: pretty; }
        [data-specimen-row] { list-style: none; margin: var(--ta-space-3) 0 0; padding: 0; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: var(--ta-space-3); }
        [data-specimen-row] > li { margin: 0; padding: 0; min-width: 0; }
        [data-specimen] { position: relative; isolation: isolate; margin: 0; aspect-ratio: 4 / 3; padding: var(--ta-pad-card); }
        [data-specimen-face] { position: relative; z-index: 1; display: flex; flex-direction: column; height: auto; min-height: 100%; }
        [data-specimen-top] { display: flex; align-items: center; justify-content: space-between; }
        [data-specimen-caption] { margin-top: auto; display: flex; flex-direction: column; gap: var(--ta-space-1); }
        [data-specimen-rule] { display: block; width: 2rem; height: 2px; border-radius: 1px; background: var(--ta-accent-1); margin-bottom: var(--ta-space-1); }
        [data-specimen-name] { font-family: var(--ta-font-display); font-weight: 500; font-size: var(--ta-text-xl); line-height: 1.1; color: var(--ta-text-primary); overflow-wrap: anywhere; }
        [data-specimen-motif] { font-family: var(--ta-font-mono); font-size: var(--ta-text-2xs); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ta-text-muted); }
        [data-difference-constancy] { margin: var(--ta-space-block) 0 0; max-width: var(--ta-measure); font-size: var(--ta-text-lg); line-height: 1.55; color: var(--ta-text-primary); }
        [data-difference-next] { margin: var(--ta-space-3) 0 0; max-width: var(--ta-measure); font-size: var(--ta-text-md); line-height: 1.6; color: var(--ta-text-secondary); }
        @media (max-width: 48rem) {
          [data-specimen-row] { grid-template-columns: repeat(2, minmax(0, 1fr)); }
        }
        @media (max-width: 30rem) {
          [data-specimen-row] { gap: var(--ta-space-2); }
          [data-specimen] { aspect-ratio: 1 / 1; padding: var(--ta-space-3); }
          [data-specimen-name] { font-size: var(--ta-text-sm); }
          [data-difference] { padding-block: var(--ta-space-6); }
          [data-difference-lead], [data-difference-constancy] { font-size: var(--ta-text-md); }
        }

[data-choice] { padding-block: var(--ta-space-block); }
        [data-choice-lead] { margin: var(--ta-space-4) 0 0; max-width: var(--ta-measure); font-size: var(--ta-text-lg); line-height: 1.55; color: var(--ta-text-secondary); text-wrap: pretty; }
        [data-choice-availability] { margin: var(--ta-space-2) 0 0; max-width: var(--ta-measure); font-size: var(--ta-text-md); line-height: 1.6; color: var(--ta-text-primary); }
        [data-doors] { list-style: none; margin: var(--ta-space-block) 0 0; padding: 0; border-top: 1px solid var(--ta-border-subtle); }
        [data-doors] > li { margin: 0; padding: 0; border-bottom: 1px solid var(--ta-border-subtle); }
        [data-door] { position: relative; isolation: isolate; overflow: clip; display: grid; grid-template-columns: 2rem minmax(0, 1fr) auto; align-items: center; gap: var(--ta-space-4); padding: var(--ta-space-4) var(--ta-space-3); min-height: 6rem; color: inherit; text-decoration: none; box-shadow: inset 2px 0 0 var(--ta-accent-3); transition: transform var(--ta-dur-fast) var(--ta-ease-enter), box-shadow var(--ta-dur-fast) var(--ta-ease-enter); }
        [data-door] > * { position: relative; z-index: 1; }
        [data-door] > [data-motif] { z-index: 0; }
        [data-door-mark] { color: var(--ta-accent-1); display: block; }
        [data-door-text] { display: grid; gap: 2px; min-width: 0; }
        [data-door-name] { font-family: var(--ta-font-display); font-weight: 500; font-size: var(--ta-display-sm); line-height: 1.05; color: var(--ta-text-primary); }
        [data-door-env] { font-family: var(--ta-font-mono); font-size: var(--ta-text-2xs); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ta-accent-1); margin-top: var(--ta-space-1); }
        [data-door-tagline] { font-size: var(--ta-text-sm); color: var(--ta-text-secondary); line-height: 1.5; }
        [data-door-action] { display: flex; align-items: center; justify-content: flex-end; min-width: 7rem; min-height: max(2.75rem, var(--ta-control-h)); }
        [data-door-cta] { pointer-events: none; }
        [data-door-status] { font-family: var(--ta-font-mono); font-size: var(--ta-text-2xs); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ta-text-muted); white-space: nowrap; }
        a[data-door]:hover, a[data-door]:focus-visible { transform: translateY(-2px); box-shadow: inset 3px 0 0 var(--ta-accent-1); }
        a[data-door]:hover [data-door-cta], a[data-door]:focus-visible [data-door-cta] { border-color: var(--ta-accent-1); color: var(--ta-text-primary); }
        a[data-door]:focus-visible { outline: 2px solid var(--ta-focus-ring); outline-offset: -2px; }
        [data-door-inert] { cursor: default; }
        [data-choice-next] { margin: var(--ta-space-block) 0 0; max-width: var(--ta-measure); font-size: var(--ta-text-md); line-height: 1.6; color: var(--ta-text-secondary); }
        @media (prefers-reduced-motion: reduce) {
          [data-door] { transition: none; }
          a[data-door]:hover, a[data-door]:focus-visible { transform: none; }
        }
        [data-reduced-motion="on"] [data-door] { transition: none; }
        [data-reduced-motion="on"] a[data-door]:hover, [data-reduced-motion="on"] a[data-door]:focus-visible { transform: none; }
        @media (max-width: 48rem) {
          [data-door] { grid-template-columns: 1.5rem minmax(0, 1fr); gap: var(--ta-space-3); padding: var(--ta-space-3) var(--ta-space-2); }
          [data-door-mark] svg { width: 24px; height: 24px; }
          [data-door-action] { grid-column: 2; justify-content: flex-start; min-width: 0; }
          [data-door-name] { font-size: var(--ta-text-xl); }
          /* equal weight: every row reserves two tagline lines so length of copy never changes the door's size */
          [data-door-tagline] { min-height: 3em; }
        }
        @media (max-width: 30rem) {
          [data-choice] { padding-block: var(--ta-space-6); }
          [data-choice-lead] { font-size: var(--ta-text-md); }
          [data-doors] { margin-top: var(--ta-space-6); }
          [data-door-tagline] { font-size: var(--ta-text-xs); }
        }

/* ── STICKY RELEASE RULE (see ENTER_STICKY_RULE) ─────────────────── */
        @media (max-width: 47.99rem), (max-height: 29.99rem), (prefers-reduced-motion: reduce) {
          section[data-scene="enter"] { height: auto !important; min-height: 0 !important; }
          section[data-scene="enter"] > div { position: static !important; min-height: 0 !important; }
        }
        [data-reduced-motion="on"] section[data-scene="enter"] { height: auto !important; min-height: 0 !important; }
        [data-reduced-motion="on"] section[data-scene="enter"] > div { position: static !important; min-height: 0 !important; }
        section[data-scene="enter"] > div { padding-block: var(--ta-space-6); box-sizing: border-box; }

        /* ── STAGE ──────────────────────────────────────────────────────── */
        [data-enter-stage] { margin: var(--ta-space-4) 0 0; border: 1px solid var(--ta-border-subtle); border-radius: var(--ta-radius-2); overflow: clip; }
        [data-enter-stage] [data-switch-surface] { min-height: min(26rem, 46vh) !important; display: flex; flex-direction: column; }
        [data-enter-stage] [data-switch-surface] > div:not([data-switch-layer]):not([data-switch-announce]) { flex: 1; display: flex; }
        [data-enter-identity] { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: var(--ta-space-5); align-items: start; align-content: center; padding: var(--ta-space-6) var(--ta-space-8); width: 100%; }
        [data-enter-mark] { color: var(--ta-accent-1); display: block; line-height: 0; }
        [data-enter-mark] svg { width: 72px; height: 72px; }
        [data-enter-name] { margin: 0; font-family: var(--ta-font-display); font-weight: 500; font-size: var(--ta-display-md); line-height: 1; color: var(--ta-text-primary); }
        [data-enter-env] { font-family: var(--ta-font-mono); font-size: var(--ta-text-xs); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ta-accent-1); margin: var(--ta-space-2) 0 0; }
        [data-enter-tagline] { margin: var(--ta-space-3) 0 0; font-size: var(--ta-text-lg); color: var(--ta-text-secondary); max-width: 28rem; line-height: 1.45; }
        [data-enter-action] { margin-top: var(--ta-space-5); display: grid; gap: var(--ta-space-3); justify-items: start; }
        [data-enter-depth] { margin: 0; font-size: var(--ta-text-sm); color: var(--ta-text-muted); max-width: 28rem; }
        [data-enter-status] { font-family: var(--ta-font-mono); font-size: var(--ta-text-xs); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ta-text-muted); display: inline-flex; align-items: center; min-height: var(--ta-control-h); padding-inline: var(--ta-space-1); box-shadow: inset 0 -1px 0 var(--ta-accent-3); }
        [data-enter-caption] { margin: var(--ta-space-3) 0 0; }

        /* ── CONTROL — steps, never chooses ─────────────────────────────── */
        [data-enter-control] { display: flex; flex-wrap: wrap; align-items: center; gap: var(--ta-space-3); margin-top: var(--ta-space-5); }
        [data-enter-control] button { min-height: var(--ta-target-min); min-width: var(--ta-target-min); }
        [data-enter-control] button:focus-visible { outline: 2px solid var(--ta-focus-ring); outline-offset: 2px; }
        [data-enter-position] { font-family: var(--ta-font-mono); font-size: var(--ta-text-2xs); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ta-text-muted); margin: 0 0 0 var(--ta-space-2); }

        @media (max-width: 48rem) {
          [data-enter-identity] { grid-template-columns: 1fr; gap: var(--ta-space-4); padding: var(--ta-space-6) var(--ta-space-5); }
          [data-enter-mark] svg { width: 48px; height: 48px; }
          [data-enter-name] { font-size: var(--ta-display-sm); }
          [data-enter-tagline] { font-size: var(--ta-text-md); }
          [data-enter-stage] [data-switch-surface] { min-height: 0 !important; }
        }
        @media (max-width: 30rem) {
          [data-enter-identity] { padding: var(--ta-space-5) var(--ta-space-4); }
          [data-enter-name] { font-size: var(--ta-display-xs); }
          [data-enter-position] { width: 100%; margin: 0; }
        }

[data-people-lead] { margin: var(--ta-space-4) 0 0; font-family: var(--ta-font-display); font-weight: 400; font-size: var(--ta-text-2xl); line-height: 1.35; color: var(--ta-text-primary); max-width: 30ch; }
        [data-people-lines] { margin: var(--ta-space-6) 0 0; padding: var(--ta-space-6) 0 0; border-top: 1px solid var(--ta-border-subtle); max-width: var(--ta-measure); display: grid; gap: var(--ta-space-3); }
        [data-people-lines] p { margin: 0; font-size: var(--ta-text-lg); line-height: 1.5; color: var(--ta-text-secondary); }
        [data-people-lines] em { font-style: normal; color: var(--ta-text-primary); }
        [data-status] { display: inline-flex; align-items: baseline; gap: var(--ta-space-2); font-family: var(--ta-font-mono); font-size: var(--ta-text-sm); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ta-text-secondary); box-shadow: inset 0 -1px 0 var(--ta-border-strong); padding-bottom: 2px; }
        [data-status][data-state="live"] { color: var(--ta-text-primary); box-shadow: inset 0 -1px 0 var(--ta-text-primary); }
        [data-people-status] { margin: var(--ta-space-6) 0 0; font-size: var(--ta-text-md); color: var(--ta-text-secondary); }
        @media (max-width: 30rem) { [data-people-lead] { font-size: var(--ta-text-xl); } [data-people-lines] p { font-size: var(--ta-text-md); } }

[data-practice-lead] { margin: var(--ta-space-3) 0 0; font-size: var(--ta-text-lg); line-height: 1.5; color: var(--ta-text-secondary); max-width: var(--ta-measure); }
        [data-thread] { list-style: none; margin: var(--ta-space-8) 0 0; padding: 0 0 0 var(--ta-space-6); position: relative; max-width: 44rem; }
        [data-thread]::before { content: ""; position: absolute; left: 0; top: 0.6em; bottom: 0.6em; width: 1px; background: var(--ta-border-strong); }
        [data-beat] { position: relative; margin: 0; }
        [data-beat] + [data-beat] { margin-top: var(--ta-space-8); }
        [data-beat]:nth-child(even) { padding-left: clamp(0px, 10vw, 6rem); }
        [data-beat]::before { content: ""; position: absolute; left: calc(-1 * var(--ta-space-6) - 3px); top: 0.55em; width: 7px; height: 7px; border-radius: 50%; background: var(--ta-surface-base); border: 1px solid var(--ta-text-primary); }
        [data-beat-label] { font-family: var(--ta-font-display); font-weight: 500; font-size: var(--ta-text-xl); color: var(--ta-text-primary); margin: 0; }
        [data-beat-text] { margin: var(--ta-space-2) 0 0; font-size: var(--ta-text-lg); line-height: 1.5; color: var(--ta-text-secondary); max-width: 46ch; }
        [data-beat-status] { margin: var(--ta-space-2) 0 0; }
        [data-status] { display: inline-flex; align-items: baseline; gap: var(--ta-space-2); font-family: var(--ta-font-mono); font-size: var(--ta-text-sm); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ta-text-secondary); box-shadow: inset 0 -1px 0 var(--ta-border-strong); padding-bottom: 2px; }
        [data-status][data-state="live"] { color: var(--ta-text-primary); box-shadow: inset 0 -1px 0 var(--ta-text-primary); }
        [data-consolidated] { margin: var(--ta-space-12) 0 0; padding-top: var(--ta-space-6); border-top: 1px solid var(--ta-border-subtle); max-width: var(--ta-measure); }
        [data-consolidated] p { margin: 0; font-size: var(--ta-text-md); line-height: 1.55; color: var(--ta-text-primary); }
        [data-consolidated] p + p { margin-top: var(--ta-space-2); color: var(--ta-text-secondary); }
        [data-outro] { margin: var(--ta-space-6) 0 0; font-family: var(--ta-font-display); font-size: var(--ta-text-lg); color: var(--ta-text-muted); }
        @media (max-width: 30rem) { [data-beat]:nth-child(even) { padding-left: 0; } [data-beat-text] { font-size: var(--ta-text-md); } }

[data-promise-lead] { margin: var(--ta-space-3) 0 0; font-family: var(--ta-font-display); font-weight: 400; font-size: var(--ta-text-2xl); line-height: 1.35; color: var(--ta-text-primary); max-width: 32ch; }
        [data-markers] { list-style: none; margin: var(--ta-space-8) 0 0; padding: 0; display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); gap: 0; position: relative; }
        [data-markers]::before { content: ""; position: absolute; left: 4px; right: 4px; top: 4px; height: 1px; background: var(--ta-border-strong); }
        [data-marker] { position: relative; padding: var(--ta-space-4) var(--ta-space-3) 0 0; min-width: 0; }
        [data-marker]::before { content: ""; position: absolute; left: 0; top: 0; width: 9px; height: 9px; border-radius: 50%; border: 1px solid var(--ta-text-primary); background: var(--ta-surface-base); box-sizing: border-box; }
        [data-marker][data-state="done"]::before { background: var(--ta-text-primary); }
        [data-marker-label] { margin: 0; font-size: var(--ta-text-sm); line-height: 1.35; color: var(--ta-text-primary); font-weight: 500; }
        [data-marker-state] { margin: var(--ta-space-1) 0 0; font-family: var(--ta-font-mono); font-size: var(--ta-text-2xs); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ta-text-secondary); }
        [data-marker][data-state="ahead"] [data-marker-label] { font-weight: 400; }
        [data-mastery] { margin: var(--ta-space-8) 0 0; padding-top: var(--ta-space-6); border-top: 1px solid var(--ta-border-subtle); max-width: var(--ta-measure); }
        [data-mastery] p { margin: 0; font-size: var(--ta-text-lg); line-height: 1.5; color: var(--ta-text-primary); }
        [data-mastery-status] { margin: var(--ta-space-3) 0 0 !important; font-size: var(--ta-text-md) !important; color: var(--ta-text-secondary) !important; }
        [data-status] { display: inline-flex; align-items: baseline; font-family: var(--ta-font-mono); font-size: var(--ta-text-sm); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ta-text-secondary); box-shadow: inset 0 -1px 0 var(--ta-border-strong); padding-bottom: 2px; }
        [data-status][data-state="live"] { color: var(--ta-text-primary); box-shadow: inset 0 -1px 0 var(--ta-text-primary); }
        [data-closing] { margin: var(--ta-space-6) 0 0; font-family: var(--ta-font-display); font-size: var(--ta-text-lg); color: var(--ta-text-muted); }
        /* Reflow: below 48rem (and therefore at 400% zoom on any desktop) the row becomes a vertical sequence on one hairline. */
        @media (max-width: 48rem) {
          [data-markers] { grid-template-columns: 1fr; gap: var(--ta-space-3); padding-left: var(--ta-space-6); }
          [data-markers]::before { left: 4px; right: auto; top: 4px; bottom: 4px; width: 1px; height: auto; }
          [data-marker] { padding: 0; }
          [data-marker]::before { left: calc(-1 * var(--ta-space-6)); top: 0.35em; }
          [data-marker-label] { font-size: var(--ta-text-md); }
          [data-promise-lead] { font-size: var(--ta-text-xl); }
        }

[data-return] { padding: var(--ta-space-8) 0; max-width: 40rem; }
        [data-return-lead] { margin: var(--ta-space-4) 0 0; font-size: var(--ta-text-lg); line-height: 1.5; color: var(--ta-text-secondary); }
        [data-return-open] { margin: var(--ta-space-2) 0 0; font-size: var(--ta-text-md); color: var(--ta-text-secondary); }
        [data-return-cta] { margin: var(--ta-space-6) 0 0; display: flex; flex-wrap: wrap; gap: var(--ta-space-3); }
        [data-return-cta] a { min-height: 48px; min-width: 48px; }
        [data-return-closing] { margin: var(--ta-space-8) 0 0; padding-top: var(--ta-space-4); border-top: 1px solid var(--ta-border-subtle); font-family: var(--ta-font-display); font-size: var(--ta-text-lg); color: var(--ta-text-muted); }
        @media (max-width: 30rem) { [data-return-cta] a { width: 100%; justify-content: center; } }
